import{_ as n,C as r,o as s,c as d,j as o,a,E as t,al as l}from"./chunks/framework.7vp1BMOE.js";const _=JSON.parse('{"title":"GNSS-Degraded & Denied Flight (\\"Dead-Reckoning\\" Mode)","description":"","frontmatter":{},"headers":[],"relativePath":"en/advanced_config/gnss_degraded_or_denied_flight.md","filePath":"en/advanced_config/gnss_degraded_or_denied_flight.md"}'),c={name:"en/advanced_config/gnss_degraded_or_denied_flight.md"};function h(g,e,u,m,f,p){const i=r("Badge");return s(),d("div",null,[e[0]||(e[0]=o("h1",{id:"gnss-degraded-denied-flight-dead-reckoning-mode",tabindex:"-1"},[a('GNSS-Degraded & Denied Flight ("Dead-Reckoning" Mode) '),o("a",{class:"header-anchor",href:"#gnss-degraded-denied-flight-dead-reckoning-mode","aria-label":'Permalink to "GNSS-Degraded & Denied Flight ("Dead-Reckoning" Mode)"'},"​")],-1)),t(i,{type:"tip",text:"PX4 v1.17"}),e[1]||(e[1]=a()),t(i,{type:"warning",text:"Experimental"}),e[2]||(e[2]=l('<div class="warning custom-block"><p class="custom-block-title">Experimental</p><p>This is a new feature with limited real-world testing. It is intended for GNSS dropout scenarios (not pure GNSS-denied from takeoff), and requires that alternative velocity/position sensors are available.</p><p>Please <a href="./../getting_started/flight_reporting#sharing-the-log-files-for-review-by-px4-developers">share your related test logs</a> to help us verify and harden it.</p></div><p>PX4 is default-configured for outdoor flight with a reliable GNSS signal, but it can also be set up in &quot;dead-reckoning mode&quot; to more gracefully handle environments where GNSS is intermittently degraded or denied during flight.</p><p>This section describes the differences between automatic and dead-reckoning modes, the circumstances in which each should be used, and how dead-reckoning is configured.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>PX4&#39;s EKF2 navigation has two modes for handling when GNSS data is determined to be unreliable:</p><ul><li><strong>Automatic mode</strong> (the default): Used for flying outdoors in environments where a GNSS signal is expected to be largely reliable.</li><li><strong>Dead-reckoning mode</strong>: Recommended when you want to fly missions or other position controlled modes when there is intermittent GNSS loss, such as when flying under a bridge, from outdoors into an indoor setting, or when there is GNSS jamming (it is not suitable for pure-indoor use, as a GNSS signal is required before arming).</li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Dead-reckoning mode helps for both Fixed-Wing and Multicopter vehicles. MC vehicles benefit more because they can hover when transitioning between sensor regimes. FW needs continuous accurate velocity/position during the entire mission arc, making sensor transitions trickier.</p></div><h2 id="mode-comparison" tabindex="-1">Mode Comparison <a class="header-anchor" href="#mode-comparison" aria-label="Permalink to &quot;Mode Comparison&quot;">​</a></h2><p>The following sections provide more detail about each of the modes and when they should be used.</p><h3 id="automatic-mode" tabindex="-1">Automatic Mode <a class="header-anchor" href="#automatic-mode" aria-label="Permalink to &quot;Automatic Mode&quot;">​</a></h3><p>In Automatic mode the EKF2 resets if GNSS is lost and no other sources of position are available. This can result in a <a href="./../config/safety#position-loss-failsafe">position loss failsafe</a> and may trigger a shift into a mode that does not require global position, including stopping missions.</p><p>This is desirable if the GNSS signal is likely to be recovered quickly and there are no mechanisms to estimate position when GNSS is unavailable.</p><p>Use Automatic (default) when:</p><ul><li>Flying in open sky with reliable GNSS throughout the mission.</li><li>You want the EKF to reset to GNSS when it becomes available again.</li><li>Operating in environments where GNSS is either good or completely unavailable (binary state).</li></ul><h3 id="dead-reckoning-mode" tabindex="-1">Dead-Reckoning Mode <a class="header-anchor" href="#dead-reckoning-mode" aria-label="Permalink to &quot;Dead-Reckoning Mode&quot;">​</a></h3><p>In dead-reckoning mode, EKF2 stops fusing GNSS data when it becomes unreliable and prevents EKF2 resets — provided there are other sources of position or velocity data that can be fused. This ensures that the vehicle can continue flying missions and other position controlled modes when GNSS is lost.</p><p>When GNSS is recovered it will be fused with other measurements when tests indicate it can be trusted. This may cause jerky movements in position controlled modes if the estimate has drifted. This mode relies on having additional position or velocity sensors and must also have a reliable GNSS signal at boot.</p><p>Use Dead-Reckoning when:</p><ul><li><strong>Transitioning between GNSS and non-GNSS environments</strong> (flying into buildings, under bridges, through tree cover).</li><li>You have <strong>redundant sensors</strong> (optical flow, VIO, rangefinder, quality baro) that can maintain position estimation.</li><li>Flying <strong>missions that cross GPS-denied areas</strong> where you want continuous operation rather than failsafe.</li><li><strong>Urban environments</strong> or other areas with intermittent GNSS quality.</li><li>You want to <strong>avoid EKF resets and jumps</strong> when GNSS recovers (smoother transitions).</li></ul><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>To use dead-reckoning mode, the vehicle must have an alternative source of position or velocity information, such as an <a href="./../sensor/optical_flow">Optical Flow</a> sensor or <a href="./../computer_vision/visual_inertial_odometry">VIO</a> setup.</p><p>To enable the mode:</p><ol><li>Set <a href="./../advanced_config/parameter_reference#EKF2_GPS_MODE">EKF2_GPS_MODE</a> to <code>1</code>.</li><li>Ensure that GNSS arming checks are enabled (a reliable GNSS signal is required before arming): <ul><li><a href="./../advanced_config/parameter_reference#COM_ARM_WO_GPS">COM_ARM_WO_GPS</a> - set to <code>0</code></li><li><a href="./../advanced_config/parameter_reference#EKF2_GPS_CHECK">EKF2_GPS_CHECK</a> - set to default.</li></ul></li></ol><h2 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See Also&quot;">​</a></h2><ul><li><a href="./../advanced_config/tuning_the_ecl_ekf#gnss-fault-detection">GNSS Fault Detection</a> in <em>Using PX4&#39;s Navigation Filter (EKF2)</em></li><li><a href="https://www.youtube.com/watch?v=CMGQJNPiTJg" target="_blank" rel="noreferrer">Fuse, Reset, or Reject? Handling Various Data-sources in EKF2</a> - <em>PX4 Developer Summit 2025</em>, Marco Hauswirth, Auterion AG</li></ul>',25))])}const b=n(c,[["render",h]]);export{_ as __pageData,b as default};
